{"content":"#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define SAMPLE_RATE 44100
#define DURATION_SEC 2
#define NUM_SAMPLES (SAMPLE_RATE * DURATION_SEC)
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define NUM_TONES 2

static const double kFreqs[NUM_TONES] = {440.0, 880.0};
static const double kAmps[NUM_TONES] = {0.27, 0.18};
static const double kScaleFactor = 1.0;

static void write_u16le(FILE *fp, uint16_t v)
{
    uint8_t b[2];
    b[0] = (uint8_t)(v & 0xFFu);
    b[1] = (uint8_t)((v >> 8) & 0xFFu);
    fwrite(b, 1, 2, fp);
}

static void write_u32le(FILE *fp, uint32_t v)
{
    uint8_t b[4];
    b[0] = (uint8_t)(v & 0xFFu);
    b[1] = (uint8_t)((v >> 8) & 0xFFu);
    b[2] = (uint8_t)((v >> 16) & 0xFFu);
    b[3] = (uint8_t)((v >> 24) & 0xFFu);
    fwrite(b, 1, 4, fp);
}

void write_wav_header(FILE *fp, uint32_t num_samples)
{
    uint32_t data_size = num_samples * (uint32_t)NUM_CHANNELS * (BITS_PER_SAMPLE / 8);
    uint32_t chunk_size = 36 + data_size;
    uint32_t byte_rate = (uint32_t)SAMPLE_RATE * (uint32_t)NUM_CHANNELS * (BITS_PER_SAMPLE / 8);
    uint16_t block_align = (uint16_t)(NUM_CHANNELS * (BITS_PER_SAMPLE / 8));

    fwrite("RIFF", 1, 4, fp);
    write_u32le(fp, chunk_size);
    fwrite("WAVE", 1, 4, fp);
    fwrite("fmt ", 1, 4, fp);
    write_u32le(fp, 16);
    write_u16le(fp, 1);
    write_u16le(fp, (uint16_t)NUM_CHANNELS);
    write_u32le(fp, (uint32_t)SAMPLE_RATE);
    write_u32le(fp, byte_rate);
    write_u16le(fp, block_align);
    write_u16le(fp, (uint16_t)BITS_PER_SAMPLE);
    fwrite("data", 1, 4, fp);
    write_u32le(fp, data_size);
}

int16_t quantize_sample(double sample_float)
{
    double scaled = sample_float * 32767.0 * kScaleFactor;
    int v = (int)scaled;
    if (v > 32767) {
        v = 32767;
    }
    if (v < -32768) {
        v = -32768;
    }
    return (int16_t)v;
}

void generate_samples(int16_t *buffer, uint32_t num_samples)
{
    uint32_t i;
    int k;
    for (i = 0; i < num_samples; i++) {
        double t = (double)i / (double)SAMPLE_RATE;
        double acc = 0.0;
        for (k = 0; k < NUM_TONES; k++) {
            acc += kAmps[k] * sin(2.0 * M_PI * kFreqs[k] * t);
        }
        buffer[i] = quantize_sample(acc);
    }
}

int main(void)
{
    FILE *fp = NULL;
    int16_t *samples = NULL;

    samples = (int16_t *)malloc(sizeof(int16_t) * NUM_SAMPLES);
    if (samples == NULL) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }

    generate_samples(samples, NUM_SAMPLES);

    fp = fopen("reconstructed.wav", "wb");
    if (fp == NULL) {
        fprintf(stderr, "cannot open output file\n");
        free(samples);
        return 1;
    }

    write_wav_header(fp, NUM_SAMPLES);
    fwrite(samples, sizeof(int16_t), NUM_SAMPLES, fp);
    fclose(fp);
    free(samples);
    return 0;
}
